  "MigaBuilder Shop: Website, CV and Business Templates": { es: "Tienda MigaBuilder: plantillas de webs, currículums y negocios", ar: "متجر MigaBuilder: قوالب مواقع وسير ذاتية وأعمال", zh: "MigaBuilder 商店：网站、简历和商务模板", sw: "Duka la MigaBuilder: Violezo vya tovuti, CV na biashara", sv: "MigaBuilder-butiken: mallar för webbplatser, cv och företag", de: "MigaBuilder-Shop: Vorlagen für Websites, Lebensläufe und Unternehmen", pt: "Loja MigaBuilder: modelos de sites, currículos e negócios", fr: "Boutique MigaBuilder : modèles de sites, CV et documents professionnels" },
  "MigaBuilder Shop": { es: "Tienda MigaBuilder", ar: "متجر MigaBuilder", zh: "MigaBuilder 商店", sw: "Duka la MigaBuilder", sv: "MigaBuilder-butiken", de: "MigaBuilder-Shop", pt: "Loja MigaBuilder", fr: "Boutique MigaBuilder" },
